const sessionId = typeof $json.sessionId === 'string' ? $json.sessionId.trim() : '';
const requestId = typeof $json.requestId === 'string' ? $json.requestId.trim() : '';
const jobId = typeof $json.jobId === 'string' ? $json.jobId.trim() : '';
const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
let error = null;
if (!uuidPattern.test(sessionId) || !uuidPattern.test(requestId)) error = { code: 'INVALID_SESSION', message: 'The research check needs a valid conversation and request ID.' };
else if (!/^[A-Za-z0-9:_-]{1,160}$/.test(jobId)) error = { code: 'INVALID_JOB_ID', message: 'Use the exact job ID returned when domain research started.' };
const proposedInput = { sessionId, requestId, jobId };
return { json: { valid: error === null, ...proposedInput, proposedInput, ...(error ? { response: { ok: false, error } } : {}) } };

const input = $('Validate Completion Input').first().json;
const status = String($json.status ?? '');
const sameJob = $json.jobId === input.jobId;
let shouldSave = false;
let response;
if (sameJob && ['completed', 'partial'].includes(status)) {
  shouldSave = true;
  response = { ok: true, jobId: input.jobId, domain: String($json.domain ?? ''), status, saved: false, message: 'Research is ready and is being saved to local business memory.' };
} else if (sameJob && ['queued', 'running'].includes(status)) {
  response = { ok: true, jobId: input.jobId, domain: String($json.domain ?? ''), status, saved: false, currentStep: String($json.currentStep ?? ''), message: String($json.message ?? 'Domain research is still running. Check again shortly.') };
} else if (sameJob && status === 'failed') {
  response = { ok: false, jobId: input.jobId, status, error: { code: 'RESEARCH_FAILED', message: String($json.error ?? 'Domain research failed.') } };
} else {
  response = { ok: false, error: { code: 'RESEARCH_STATUS_FAILED', message: String($json.message ?? $json.error?.message ?? 'The research job could not be read.') } };
}
return { json: { ...input, research: $json, shouldSave, response } };

const evaluated = $('Evaluate Research Status').first().json;
const memory = $json.memory;
const saved = memory && memory.jobId === evaluated.jobId && memory.domain === evaluated.response.domain;
const response = saved
  ? { ok: true, jobId: evaluated.jobId, domain: memory.domain, status: memory.status, saved: true, memory, message: memory.status === 'partial' ? 'Partial domain research was saved to local business memory with its warnings.' : 'Domain research was saved to local business memory.' }
  : { ok: false, jobId: evaluated.jobId, error: { code: 'MEMORY_SAVE_FAILED', message: String($json.error?.message ?? 'Completed research could not be saved to local business memory.') } };
return { json: { ...evaluated, response } };

const input = $('Validate Completion Input').first().json;
const response = $json.response ?? { ok: false, error: { code: 'RESEARCH_STATUS_FAILED', message: 'The research job could not be checked.' } };
return { json: { occurredAt: new Date().toISOString(), sessionId: input.sessionId, requestId: input.requestId, toolName: 'complete_domain_research', proposedInput: JSON.stringify(input.proposedInput ?? {}), result: JSON.stringify(response), error: response.ok === false ? String(response.error?.message ?? 'Tool failed') : '', response } };

const prepared = $('Prepare Audit').item.json;
const response = { ...prepared.response };
if (!Number.isInteger($json.id)) response.auditWarning = 'The tool result could not be written to the local audit table.';
return { json: response };
